	// Credentials come from the parent registry, or the entry itself for a
	// registry that is not a group member.
	credURL := entry.URL
	if entry.parentURL != "" {
		credURL = entry.parentURL
	}
	var username string
	for _, reg := range b.registries {
		if reg.URL == credURL {
			username = reg.Username
			break
		}
	}
	storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
	if username == "" {
		username = storedUser
	}
	return username, storedPass
}

func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
	repo := strings.TrimSpace(b.repoInput.Value())
	if repo == "" {
		return b, nil
	}

	// Gather the requests first: a validation that starts none must leave the
	// lot in flight, its generation and its context alone.
	type request struct {
		entry                         browserRegistryEntry
		alias, apiURL, repo, user, pw string
	}
	var reqs []request
	for _, entry := range b.entries {
		if !b.selected(entry) {
			continue
		}
		username, storedPass := b.credsFor(entry)
		alias := entry.Alias
		if entry.ParentAlias != "" {
			alias = entry.ParentAlias + "/" + entry.Alias
		}
		// The prefix is applied here and nowhere else: it is then already part
		// of MultiRegistryTag.Repo, so multiImageName and registryAPIURL need to
		// know nothing about it. Teaching both would be two places free to
		// drift, which is the disagreement D39 already is (§3.18).
		normalizedRepo := joinRepoPrefix(entry.repoPrefix, normalizeRepoForRegistry(entry.URL, repo))
		reqs = append(reqs, request{entry, alias, registryAPIURL(entry.URL), normalizedRepo, username, storedPass})
	}
	if len(reqs) == 0 {
		return b, nil
	}

	ctx := b.beginRequests()
	b.tags = nil
	b.registryFilter = resultFilter{}
	b.filterInput.SetValue("")
	b.filterActive = false
	// A new search starts from the default order, not wherever the last one's
	// `.` presses left the table.
	b.tagTable.SetSort(tagColumnTag, false)

	cmds := make([]tea.Cmd, 0, len(reqs))
	for _, r := range reqs {
		b.pendingSearches++
		cmds = append(cmds, searchRegistryTagsCmd(ctx, b.gen, r.entry.key, r.entry.URL, r.alias, r.apiURL, r.repo, r.user, r.pw))
	}

	b.state = browserStateTags
	b.tagTable.Focus()
	b.rebuildTagTable()
	return b, tea.Batch(cmds...)
}

func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if b.filterActive {
		switch msg.String() {
		case "esc", "enter":
			b.filterActive = false
			b.filterInput.Blur()
			b.rebuildTagTable()
			b.resizeTagTable()
			return b, nil
		}
		return b.delegateUpdate(msg)
	}

	switch msg.String() {
	case "esc":
		b.state = browserStateInput
		b.tagTable.Blur()
		b.updateFocus()
		return b, nil
	case "/":
		b.filterActive = true
		b.filterInput.Focus()

